<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import {session,logout,clearSession,ApiError} from '../auth'
type Wallet={id:string;label:string;wallet_address:string;signer_address:string;wallet_type:string}
const router=useRouter(),menuOpen=ref(false),wallets=ref<Wallet[]>([]),selected=ref<any>(null),message=ref('')
async function api(path:string){const r=await fetch('/api/v1'+path,{credentials:'same-origin',cache:'no-store'});const data=await r.json();if(!r.ok)throw new Error();return data.data}
async function load(){try{wallets.value=(await api('/wallets')).items}catch{message.value='钱包列表加载失败。'}}
async function status(wallet:Wallet){try{selected.value=await api('/wallets/'+wallet.id+'/status')}catch{message.value='钱包状态不可用。'}}
async function signOut(){try{await logout();await router.replace('/login')}catch(e){if(e instanceof ApiError&&e.status===401){clearSession();await router.replace('/login')}else message.value='退出请求未确认，请重试。'}}
onMounted(load)
</script>
<template><div class="app-layout"><header class="mobile-header"><div class="brand"><span class="brand-mark">P</span> PolySports</div><button class="menu-button" :aria-expanded="menuOpen" aria-controls="primary-nav" @click="menuOpen=!menuOpen">菜单</button></header><aside id="primary-nav" class="sidebar" :class="{open:menuOpen}"><div class="brand sidebar-brand"><span class="brand-mark">P</span> PolySports</div><p class="nav-label">工作台</p><nav aria-label="主导航"><RouterLink to="/">总览</RouterLink><RouterLink to="/sports/football">足球赛事</RouterLink><RouterLink to="/sports/nba">NBA 赛事</RouterLink><RouterLink to="/combos">组合交易</RouterLink><RouterLink to="/orders">交易记录</RouterLink><RouterLink to="/history">历史与导出</RouterLink><RouterLink to="/wallets">钱包状态</RouterLink><RouterLink to="/system">系统管理</RouterLink></nav></aside><main class="workspace"><div class="workspace-top"><span class="breadcrumb">工作台 / 钱包状态</span><div class="account"><span>{{session.username}}</span><button class="text-button" @click="signOut">退出</button></div></div><div class="page-heading"><div><p class="eyebrow">READ ONLY</p><h1>钱包状态</h1><p class="muted">只显示服务器配置的钱包地址；不会请求签名、授权或部署。</p></div></div><p class="form-message" role="status">{{message}}</p><section class="welcome-card"><p v-if="!wallets.length">尚未配置钱包。</p><article class="market-card" v-for="wallet in wallets" :key="wallet.id"><h2>{{wallet.label}}</h2><p>类型：{{wallet.wallet_type}}</p><p class="wallet-address">钱包：{{wallet.wallet_address}}</p><p class="wallet-address">签名地址：{{wallet.signer_address}}</p><button class="text-button" @click="status(wallet)">查看只读状态</button><div v-if="selected?.wallet.id===wallet.id"><p>余额：{{selected.collateral_balance ?? '未知'}}</p><p>授权状态：{{selected.allowance_status==='unknown'?'未知':selected.allowance_status}}</p><p>地区状态：{{selected.availability==='blocked'?'受限':selected.availability==='allowed'?'本次检查允许':'未知'}} · Builder 能力：未知</p></div></article></section></main></div></template>
